	@Test
	void tupleSubclassFailureTerminatesCommittedStreamAndPreservesBufferedRows() throws Exception {
		FailingTupleServlet servlet = failingServlet();
		WorkbenchRequest request = request(WorkbenchPageProtocol.ACCEPT);
		MockHttpServletResponse response = new MockHttpServletResponse();

		servlet.service(request, response);

		List<JsonNode> records = records(response);
		assertThat(records).extracting(record -> record.path("type").asText())
				.containsExactly("head", "vars", "links", "rows", "error");
		assertThat(records.get(3).path("values").get(0).get(0).path("value").asText()).isEqualTo("completed row");
		assertThat(records.getLast().path("status").asInt()).isEqualTo(400);
		assertThat(records.getLast().path("message").asText()).isEqualTo("bad tuple parameter");
		assertThat(response.isCommitted()).isTrue();
		assertThat(response.getStatus()).isEqualTo(200);
	}

	@Test
	void bufferedNativePageModelHasBadRequestHttpStatusAndOneErrorTerminal() throws Exception {
		FailingTupleServlet servlet = failingServlet();
		WorkbenchRequest request = request("text/html");
		request.setAttribute(WorkbenchPageProtocol.NATIVE_HTML_POST_PAGE_MODEL_ATTRIBUTE, Boolean.TRUE);
		MockHttpServletResponse response = new MockHttpServletResponse();
		WorkbenchPageModelResponseWrapper bufferedResponse = new WorkbenchPageModelResponseWrapper(response);

		servlet.service(request, bufferedResponse);
		request.removeAttribute(WorkbenchPageProtocol.NATIVE_HTML_POST_PAGE_MODEL_ATTRIBUTE);
		bufferedResponse.complete(request, null, "test-tuple");

		assertThat(response.getStatus()).isEqualTo(400);
		assertThat(response.getContentType()).startsWith("text/html");
		String html = response.getContentAsString();
		assertThat(html).contains("data-workbench-initial-model=");
		String encodedModel = html.split("data-workbench-initial-model=\"")[1].split("\"", 2)[0];
		List<JsonNode> records = new String(Base64.getUrlDecoder().decode(encodedModel), StandardCharsets.UTF_8)
				.lines()
				.map(JSON_MAPPER::readTree)
				.toList();
		assertThat(records).extracting(record -> record.path("type").asText())
				.containsExactly("head", "vars", "links", "rows", "error");
		assertThat(records.getLast().path("message").asText()).isEqualTo("bad tuple parameter");
	}

